import{_ as e,c as p,o as r,af as i}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"10、【履】 兑下乾上","description":"周易尚氏学 - 10、【履】 兑下乾上","frontmatter":{"title":"10、【履】 兑下乾上","description":"周易尚氏学 - 10、【履】 兑下乾上"},"headers":[],"relativePath":"zh/classics/shangshi/015.md","filePath":"zh/classics/shangshi/015.md"}'),s={name:"zh/classics/shangshi/015.md"};function h(t,a,l,n,c,d){return r(),p("div",null,[...a[0]||(a[0]=[i('<h1 id="_10、【履】-兑下乾上" tabindex="-1">10、【履】 兑下乾上 <a class="header-anchor" href="#_10、【履】-兑下乾上" aria-label="Permalink to “10、【履】 兑下乾上”">​</a></h1><p>尔雅释言。履者礼也。故太玄即拟为礼。礼莫大于辩上下。定尊卑。卦上天下泽。尊卑判然。人之行履。莫大于是。故曰履。乾为虎。四虎尾。兑在乾后。故曰履虎尾。履蹑也。言三蹑乾后也。乾为人。兑口为哸。人在外故不受哸。彖传曰。柔履刚。言三步乾刚之后也。荀爽谓三履二。祇以下卦为说。岂知卦名。皆合上下卦取义。无取一卦者。且三履二。是柔乘刚。与卦义正相背。非也。</p><p>彖曰。履。柔履刚也。说而应乎乾。是以履虎尾。不哸人。亨。刚中正。履帝位而不疚。光明也。</p><p>说而应乎乾。谓三应上也。五下履巽。男为病宜有疚。疚即病也。然而不疚者。以五履帝位而中正也。互离为日故光明。人知坎为病。不知巽亦为病。故说疚象无有合者。岂知巽为陨落。当然亦为病。易林。巽之鼎云。病伤不治。以鼎下巽为病。兑之蛊云。疮痍多病。以蛊上艮为疮痍。下巽为病也。由易林推之易。遁九三云。有疾厉。丰六二云。往得疑疾。易原以巽为疾病。故易林本之也。(集解。荀注多利贞二字。兑秋乾冬正合。然他本皆无。)</p><p>象曰。上天下泽。履。君子以辨上下。定民志。</p><p>谦坤为民为志。艮止为定。民志之所以不定者。以不知上下也。上天下泽。尊卑显然。故君子法之。以定民志。周公制礼。是其事也。</p><p>初九。素履。往无咎。</p><p>四无应。二阳。阳遇阳得敌。宜有咎。然而无咎者。以能素位而行也。故曰素履。言屏去浮华。安常蹈素。循分自守也。能如此。故往无咎。</p><h3 id="象曰。素履之往。独行愿也。" tabindex="-1">象曰。素履之往。独行愿也。 <a class="header-anchor" href="#象曰。素履之往。独行愿也。" aria-label="Permalink to “象曰。素履之往。独行愿也。”">​</a></h3><p>得敌无应。故曰独行。甘于独行。故无咎也。先儒于同性相违之义知者鲜。故独行之故。无有详者。</p><p>九二。履道坦坦。幽人贞吉。</p><p>伏艮为道路。比阴得中。故坦坦。坦坦者宽平也。兑为昧无应。故曰幽人。居中故贞吉。</p><h3 id="象曰。幽人贞吉。中不自乱也。" tabindex="-1">象曰。幽人贞吉。中不自乱也。 <a class="header-anchor" href="#象曰。幽人贞吉。中不自乱也。" aria-label="Permalink to “象曰。幽人贞吉。中不自乱也。”">​</a></h3><p>象多释贞为正。此以不乱释贞。明贞有正定二义也。</p><p>六三。眇能视。跛能履。履虎尾。哸人凶。武人为于大君。</p><p>说文。眇。一目小也。兑为小。离目。故曰眇能视。震为履。二三半震。故曰跛能履。眇而视。跛而履。皆力不足而不止之象。故象曰不足以有明不足以与行也。三正在乾虎后故曰履虎尾。彖言不哸。此言哸者。盖以上下卦言。乾虎在外。兑在后。故不哸。而以爻言。四虎尾。上虎首。三应在上。上必来三。虎首回噬。故三独受哸而凶也。伏震为武人。乾为大君。三承乾。故曰武人为于大君。言武人忠于大君。阴顺阳。代终事。与讼三之从王事同。象释曰志刚。刚即谓大君。志刚即释为义也。虞翻谓三失位。变得正成乾。直以武人变为大君。失之。近师俞荫甫谓此与坤讼六三之或从王事同义。略露曙光。特又以三升乾上释为字仍误也。震武之象。国语重耳筮遇贞屯悔豫。皆有震。曰车有震武。武足迹也。震健。故震为武。易林本之。遇震即言武。于是履及巽之武人。象始大明。</p><h3 id="象曰。眇能视。不足以有明也。跛能履。不足以与行也-咥人之凶。位不当也。武人为于大君。志刚也。" tabindex="-1">象曰。眇能视。不足以有明也。跛能履。不足以与行也，咥人之凶。位不当也。武人为于大君。志刚也。 <a class="header-anchor" href="#象曰。眇能视。不足以有明也。跛能履。不足以与行也-咥人之凶。位不当也。武人为于大君。志刚也。" aria-label="Permalink to “象曰。眇能视。不足以有明也。跛能履。不足以与行也，咥人之凶。位不当也。武人为于大君。志刚也。”">​</a></h3><p>三承重阳。故曰志刚。言志在顺阳而行。即坤六三讼六三之所谓从王事也。巽为志。</p><p>九四。履虎尾。愬愬终吉。</p><p>子夏传。愬愬恐惧也。四当乾末。正为虎尾。乾为惕。故为惧。然下孚于三。三阴。阳得阴志行。故终吉。小畜九五云。有孚。谓孚于四阴。此与同义。又大有上九吉。随九四有孚。皆以下乘阴而吉。昔贤不究阴阳相孚之理。但云惧则吉者。非也。</p><h3 id="象日。愬愬终吉。志行也。" tabindex="-1">象日。愬愬终吉。志行也。 <a class="header-anchor" href="#象日。愬愬终吉。志行也。" aria-label="Permalink to “象日。愬愬终吉。志行也。”">​</a></h3><p>阳孚阴故曰志行。巽为志。</p><p>九五。夬履。贞厉。</p><p>夬决也。绝也。言五承乘皆阳。上下应予绝也。贞卜问。厉危也。五居互巽之上。龚陨落。故危。否九五云。其亡其亡。兑九五云。孚于剥。有厉。亦皆以居巽上。故危也。</p><h3 id="象曰。夬履贞厉。位正当也。" tabindex="-1">象曰。夬履贞厉。位正当也。 <a class="header-anchor" href="#象曰。夬履贞厉。位正当也。" aria-label="Permalink to “象曰。夬履贞厉。位正当也。”">​</a></h3><p>五正当巽上。故贞厉。</p><p>上九。视履考祥。其旋元吉。</p><p>视履谓三。祥。吉凶之朕兆。上处履之终。故可回视已往之行事。而察其善恶之征祥。三上相上下。上来三。则皆当位。故曰其旋元吉。旋复也。来也。元吉。大吉也。祥荀作详。祥详古通。</p><h3 id="象曰。元吉在上。大有庆也。" tabindex="-1">象曰。元吉在上。大有庆也。 <a class="header-anchor" href="#象曰。元吉在上。大有庆也。" aria-label="Permalink to “象曰。元吉在上。大有庆也。”">​</a></h3><p>五阳独上有应。故大有庆。</p>',30)])])}const f=e(s,[["render",h]]);export{_ as __pageData,f as default};
